Given two arrays a[] and b[], Return union of both the arrays in any order.Note: Union of two arrays is an array having all distinct elements that are present in either array.Examples:Input : a[] = [1, 2, 3, 2, 1], b[] = [3, 2, 2, 3, 3, 2]Output : [3, 2, 1]Explanation: 3, 2 and 1 are the distinct elements present in either array.Input : a[] = [1, 2, 3], b[] = [4, 5, 6]Output : [1, 2, 3, 4, 5, 6]Explanation: 1, 2, 3, 4, 5 and 6 are the elements present in either array.Try It YourselfTable of Content[Naive Approach] Using Nested Loops [Expected Approach] Using Hash Set - O(n+m) Time and O(n+m) Space[Naive Approach] Using Nested Loops The idea is to traverse both the arrays a[] and b[] and for each element, check if the element is present in the result or not. If not, then add this element to the result.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> findUnion(vector<int> &a, vector<int> &b) {
    vector<int> res;

    // Traverse through a[] and search every element
    // a[i] in result
    for (int i = 0; i < a.size(); i++) {

        // check if the element is already
        // in the result to avoid duplicates
        int j;
        for (j = 0; j < res.size(); j++)
            if (res[j] == a[i])
                break;
        if (j == res.size()) {
            res.push_back(a[i]);
        }
    }

    // Traverse through b[] and search every element
    // b[i] in result
    for (int i = 0; i < b.size(); i++) {

        // check if the element is already
        // in the result to avoid duplicates
        int j;
        for (j = 0; j < res.size(); j++)
            if (res[j] == b[i])
                break;
        if (j == res.size()) {
            res.push_back(b[i]);
        }
    }
    return res;
}

int main() {

    vector<int> a = {1, 2, 3, 2, 1};
    vector<int> b = {3, 2, 2, 3, 3, 2};

    vector<int> res = findUnion(a, b);

    for (int i = 0; i < res.size(); i++)
        cout << res[i] << " ";
    return 0;
}


